<?php
session_start(); require_once __DIR__ . '/../includes/auth.php'; require_once __DIR__ . '/../includes/audit.php'; require_once __DIR__ . '/../includes/consent.php'; requireRole('doctor');
$patientId = filter_input(INPUT_GET, 'patient_id', FILTER_VALIDATE_INT); $doctorQuery = $pdo->prepare('SELECT id FROM doctors WHERE user_id = :user_id LIMIT 1'); $doctorQuery->execute([':user_id' => $_SESSION['user_id']]); $doctorId = (int) $doctorQuery->fetchColumn();
if (!$doctorId || !$patientId) { http_response_code(404); exit('Patient data not found.'); }
 $appointmentQuery = $pdo->prepare("SELECT a.id FROM appointments a JOIN patients p ON p.id = a.patient_id WHERE a.patient_id = :patient_id AND a.doctor_id = :doctor_id AND a.status IN ('approved', 'completed') LIMIT 1"); $appointmentQuery->execute([':patient_id' => $patientId, ':doctor_id' => $doctorId]);
if (!$appointmentQuery->fetchColumn()) { logAudit('MEDICAL_DATA_ACCESS_DENIED', 'patient', $patientId, 'Medical data requested without a valid doctor appointment.'); http_response_code(403); $pageTitle = 'Appointment Required'; require __DIR__ . '/../includes/header.php'; ?><div class="alert alert-warning"><h1 class="h4">Appointment Required</h1><p class="mb-0">A valid appointment is required to access this patient&apos;s medical history.</p></div><?php require __DIR__ . '/../includes/footer.php'; exit; }
$patientQuery = $pdo->prepare('SELECT i.full_name, i.demo_health_id, i.date_of_birth, i.gender, i.mobile FROM patients p JOIN demo_health_identities i ON i.id = p.health_identity_id WHERE p.id = :patient_id LIMIT 1'); $patientQuery->execute([':patient_id' => $patientId]); $patient = $patientQuery->fetch(PDO::FETCH_ASSOC); if (!$patient) { http_response_code(404); exit('Patient not found.'); }
$accessQuery = $pdo->prepare("SELECT u.username, d.doctor_name, cr.purpose, cr.requested_data, cr.expires_at FROM consent_requests cr JOIN users u ON u.id = cr.requested_by LEFT JOIN doctors d ON d.user_id = u.id JOIN consent_records record ON record.consent_request_id = cr.id WHERE cr.patient_id = :patient_id AND cr.requested_by = :requester_id AND cr.status = 'approved' AND record.decision = 'approved' ORDER BY record.decision_at DESC LIMIT 1"); $accessQuery->execute([':patient_id' => $patientId, ':requester_id' => $_SESSION['user_id']]); $access = $accessQuery->fetch(PDO::FETCH_ASSOC);
$recordsQuery = $pdo->prepare('SELECT record_type, record_title, record_description, created_at FROM medical_records WHERE patient_id = :patient_id ORDER BY created_at DESC'); $recordsQuery->execute([':patient_id' => $patientId]); $records = $recordsQuery->fetchAll(PDO::FETCH_ASSOC); logAudit('MEDICAL_DATA_ACCESSED', 'patient', $patientId, 'Protected patient data accessed with valid consent.'); $pageTitle = 'Authorized Patient Data'; require __DIR__ . '/../includes/header.php';
?><div class="hero-panel p-4 rounded-3 mb-4"><p class="eyebrow">Authorized access</p><h1 class="h2"><?= e($patient['full_name']) ?></h1><p class="mb-2"><?= e($patient['demo_health_id']) ?> | <?= e($patient['gender']) ?> | <?= e($patient['date_of_birth']) ?></p><?php if ($access): ?><div class="small border-top pt-3 mt-3"><strong>Requested by:</strong> <?= e($access['doctor_name'] ?: $access['username']) ?><br><strong>Purpose:</strong> <?= e($access['purpose']) ?><br><strong>Approved data:</strong> <?= e($access['requested_data']) ?><?php if ($access['expires_at']): ?><br><strong>Access expires:</strong> <?= e($access['expires_at']) ?><?php endif; ?></div><?php endif; ?></div><section class="card border-0 shadow-sm"><div class="card-body"><h2 class="h5">Medical records</h2><?php foreach ($records as $record): ?><article class="border-bottom py-3"><h3 class="h6"><?= e($record['record_title']) ?></h3><div class="small text-muted"><?= e($record['record_type']) ?> | <?= e($record['created_at']) ?></div><p class="mb-0 mt-2"><?= e($record['record_description']) ?></p></article><?php endforeach; ?><?php if (!$records): ?><p class="text-muted mb-0">No medical records available.</p><?php endif; ?></div></section><?php require __DIR__ . '/../includes/footer.php'; ?>